async fn pg_byte_backup_actual(serving:&RestoredPgServing,base:&Path,url:&str,token:&str,member:&str)->anyhow::Result<()>{
 use std::os::unix::process::CommandExt;
 let normal=std::env::current_exe()?.parent().context("Test parent absent")?.parent().context("Paired normal parent absent")?.join("starlane-notes-server");let executable=File::open(normal)?;let stamp=physical_stamp(&executable)?;let expected_hash=hash_file(&executable,executable.metadata()?.len())?;let fd=executable.as_raw_fd();
 let history=base.join("byte-backup-history");std::fs::DirBuilder::new().mode(0o700).create(&history)?;
 let target=base.join("actual-normal-byte-backup");let out=base.join("actual-byte-backup.stdout");let err=base.join("actual-byte-backup.stderr");
 let mut conn=serving.pool.acquire().await?;let profile=pg_profile_any(&mut conn).await?;let before=pg_tables_any(&mut conn,&shape_for_profile(profile)?).await?;drop(conn);
 let mut command=std::process::Command::new(format!("/proc/self/fd/{fd}"));command.arg("backup-postgres-storage").arg(&serving.proof.root.absolute).arg(&target).arg("--writers-stopped").env("DATABASE_URL",url).env("SQLITE_ENABLED","false").env("DATA_DIR",&serving.proof.root.absolute).env("JWT_SECRET",KEY).env("STORAGE_OPERATION_RECORDS_DIR",&history).env_remove("VERIFIED_RESTORE_RECORDS_DIR").stdin(std::process::Stdio::null()).stdout(File::create(out)?).stderr(File::create(err)?);
 unsafe{command.pre_exec(move||{let flags=libc::fcntl(fd,libc::F_GETFD);if flags<0||libc::fcntl(fd,libc::F_SETFD,flags&!libc::FD_CLOEXEC)<0{return Err(io::Error::last_os_error());}Ok(())});}
 let mut child=command.spawn()?;let result=async{let until=tokio::time::Instant::now()+std::time::Duration::from_secs(300);let mut real=false;loop{if let Some(status)=child.try_wait()?{ensure!(status.success(),"Actual normal byte-backup CLI refused; preserved private stderr");break;}if !real{let actual=File::open(format!("/proc/{}/exe",child.id()))?;ensure!(physical_stamp(&actual)?==stamp&&hash_file(&actual,actual.metadata()?.len())?==expected_hash,"Actual byte-backup ELF differs");real=true;}ensure!(tokio::time::Instant::now()<until,"Actual byte-backup exceeded300s");tokio::time::sleep(std::time::Duration::from_millis(100)).await;}ensure!(real,"Actual normal byte-backup process not observed");Ok::<_,anyhow::Error>(())}.await;if child.try_wait()?.is_none(){child.kill()?;}let _=child.wait()?;result?;
 serving.fence().await?;let mut conn=serving.pool.acquire().await?;ensure!(pg_tables_any(&mut conn,&shape_for_profile(profile)?).await?==before,"Byte-backup changed original application SQL");drop(conn);
 let snapshot=inspect_postgres_snapshot(&target)?;snapshot.held.fence()?;let manifest:PgSnapshotManifest=serde_json::from_slice(&snapshot.held.manifest)?;let producer=manifest.producer.as_ref().context("Actual manifest producer absent")?;ensure!(producer.package_version==env!("CARGO_PKG_VERSION")&&producer.executable_sha256==expected_hash,"Actual normal producer version/ELF metadata differs");
 let source=PgByteSourceProof::Restored(serving);let store=PgByteBackupStore::selected(&history,source.root(),None,KEY,false)?;let completed=store.latest(&source.identity()?)?.context("Actual byte-backup completion absent")?;ensure!(store.enumerate()?.len()==1,"Actual byte-backup record count differs");drop(store);
 // V105 first cold recapture refusal is retained separately; this positive
 // certifies only actual source backup and fresh original-source Admin history.
 pg_byte_admin_actual(serving,&executable,base,url,token,member,&history,&completed).await?;
 pg_byte_admin_unavailable_actual(serving,&executable,base,url,&history).await?;
 std::fs::write("/evidence/pg-byte-current-input-v106.json",serde_json::to_vec(&serde_json::json!({"path":target,"manifest_sha256":digest(&snapshot.held.manifest)}))?)?;
 println!("ACTUAL_NORMAL_CLI100MIB_BYTE_BACKUP_VERSION_ELF_RECORD_AND_FRESH_SOURCE_ADMIN_PASS;cold_recapture_not_qualified=true;verified_restore=unknown");Ok(())
}
