 unsafe{command.pre_exec(move||{for descriptor in [elf,fd]{let flags=libc::fcntl(descriptor,libc::F_GETFD);if flags<0||libc::fcntl(descriptor,libc::F_SETFD,flags&!libc::FD_CLOEXEC)<0{return Err(io::Error::last_os_error());}}Ok(())});}
