  let(status,value)=response(client.get(&endpoint).bearer_auth(token)).await?;ensure!(status==reqwest::StatusCode::OK,"Original historical projection readback refused");println!("ACTUAL_ADMIN_BYTE_BACKUP_PUBLIC_OBSERVATION:{}",serde_json::to_string(&value["backup"])?);
