  let late_key=keys[3].2.clone();let late_endpoint=endpoint.clone();let late_client=client.clone();let request=tokio::spawn(async move{late_client.get(late_endpoint).header("X-API-Key",late_key).send().await});
  let expiry=tokio::time::Instant::now()+std::time::Duration::from_millis(1000);loop{let used:Option<String>=sqlx::query_scalar("SELECT last_used_at FROM api_keys WHERE id=$1").bind(&keys[3].1).fetch_one(&serving.pool).await?;if used.is_some(){break;}ensure!(tokio::time::Instant::now()<expiry&&!request.is_finished(),"Late-revocation request did not reach actual key admission while pending");tokio::time::sleep(std::time::Duration::from_millis(10)).await;}
  let(status,_)=response(client.delete(format!("{root}{}/{}",keys[3].0,keys[3].1)).bearer_auth(token)).await?;ensure!(status.is_success(),"Actual late key revocation refused");blocked.rollback().await?;let late=request.await??;ensure!(matches!(late.status().as_u16(),401|403),"Revoked key published previously observed historical report");
